export function removeAppiumPrefixes<C extends Constraints = BaseDriverCapConstraints>(
  caps: NSCapabilities<C>,
): Capabilities<C> {
  return mapKeys(caps as Record<string, unknown>, (_, key) =>
    removeAppiumPrefix(String(key)),
  ) as Capabilities<C>;
}
