26: /**
27:  * Starts the Appium HTTP server after {@link AppiumInitializer.init}: loads drivers/plugins, binds, grid register, signals.
28:  */
29: export class AppiumMainRunner {
30:   /**
31:    * For server init: builds listeners, registers with Grid 3 if configured, and returns the server.
32:    * For non-server commands, `initResult` is empty and this resolves to `undefined`.
33:    *
34:    * @param initResult - Output of {@link AppiumInitializer.init}
35:    * @param args - Original args (used to describe `appiumHome` source in logs)
36:    */
37:   async run<
38:     Cmd extends CliCommand = CliCommandServer,
39:     SubCmd extends CliExtensionSubcommand | CliCommandSetupSubcommand | void = void,
40:   >(
41:     initResult: InitResult<Cmd>,
42:     args?: Args<Cmd, SubCmd>,
43:   ): Promise<Cmd extends CliCommandServer ? AppiumServer : void> {
44:     if (util.isEmpty(initResult)) {
45:       return undefined as Cmd extends CliCommandServer ? AppiumServer : void;
46:     }
47: 
48:     const {appiumDriver, pluginConfig, driverConfig, parsedArgs, appiumHome} =
49:       initResult as ServerInitData;
50: 
51:     const pluginClasses = await getActivePlugins(
52:       pluginConfig,
53:       parsedArgs.pluginsImportChunkSize,
54:       parsedArgs.usePlugins,
55:     );
56:     for (const [pluginClass, name] of pluginClasses) {
57:       appiumDriver.pluginClasses.set(pluginClass, name);
58:     }
59: 
60:     await logStartupInfo(parsedArgs);
61: 
62:     appiumDriver.configureGlobalFeatures();
63: 
64:     const appiumHomeSourceName = determineAppiumHomeSource(args?.appiumHome);
65:     logger.debug(`The ${appiumHomeSourceName}: ${appiumHome}`);
66: 
67:     const driverClasses = await getActiveDrivers(
68:       driverConfig,
69:       parsedArgs.driversImportChunkSize,
70:       parsedArgs.useDrivers,
71:     );
72:     const {serverOpts, normalizedBasePath} = buildServerOpts(
73:       appiumDriver,
74:       parsedArgs,
75:       driverClasses,
76:       pluginClasses,
77:     );
78: 
79:     const server = await this.startHttpServer(serverOpts, appiumDriver, normalizedBasePath);
80:     if (!server) {
81:       return undefined as Cmd extends CliCommandServer ? AppiumServer : void;
82:     }
83: 
84:     this.warnIfCorsEnabled(parsedArgs);
85:     appiumDriver.server = server;
86: 
87:     await this.registerGridOrClose(server, parsedArgs, normalizedBasePath);
88:     this.attachSignalHandlers(appiumDriver, server);
89:     this.logListeningUrl(server, parsedArgs, normalizedBasePath);
90: 
91:     driverConfig.print();
92:     pluginConfig.print([...pluginClasses.values()]);
93: 
94:     return server as Cmd extends CliCommandServer ? AppiumServer : void;
95:   }
96: 
97:   private async startHttpServer(
98:     serverOpts: ServerOpts,
99:     appiumDriver: ServerInitData['appiumDriver'],
100:     normalizedBasePath: string,
101:   ): Promise<AppiumServer | undefined> {
102:     try {
103:       return await createAppiumServer(serverOpts, appiumDriver, normalizedBasePath);
104:     } catch (err: unknown) {
105:       const message = err instanceof Error ? err.message : String(err);
106:       const stack = err instanceof Error ? err.stack : undefined;
107:       logger.error(
108:         `Could not configure Appium server. It's possible that a driver or plugin tried ` +
109:           `to update the server and failed. Original error: ${message}`,
110:       );
111:       logger.debug(stack);
112:       process.exit(1);
113:       return undefined;
114:     }
115:   }
116: 
117:   private warnIfCorsEnabled(parsedArgs: ServerInitData['parsedArgs']): void {
118:     if (parsedArgs.allowCors) {
119:       logger.warn(
120:         'You have enabled CORS requests from any host. Be careful not ' +
121:           'to visit sites which could maliciously try to start Appium ' +
122:           'sessions on your machine',
123:       );
124:     }
125:   }
126: 
127:   private async registerGridOrClose(
128:     server: AppiumServer,
129:     parsedArgs: ServerInitData['parsedArgs'],
130:     normalizedBasePath: string,
131:   ): Promise<void> {
132:     try {
133:       if (parsedArgs.nodeconfig) {
134:         await registerNode(
135:           parsedArgs.nodeconfig,
136:           parsedArgs.address,
137:           parsedArgs.port,
138:           normalizedBasePath,
139:         );
140:       }
141:     } catch (err: unknown) {
142:       await server.close();
143:       throw err;
144:     }
145:   }
146: 
147:   private attachSignalHandlers(
148:     appiumDriver: ServerInitData['appiumDriver'],
149:     server: AppiumServer,
150:   ): void {
151:     process.setMaxListeners(MAX_SERVER_PROCESS_LISTENERS);
152:     for (const signal of ['SIGINT', 'SIGTERM'] as const) {
153:       process.once(signal, async function onSignal() {
154:         logger.info(`Received ${signal} - shutting down`);
155:         try {
156:           await appiumDriver.shutdown(`The process has received ${signal} signal`);
157:           await server.close();
158:           process.exit(0);
159:         } catch (e: unknown) {
160:           logger.warn(e);
161:           process.exit(1);
162:         }
163:       });
164:     }
165:   }
166: 
167:   private logListeningUrl(
168:     server: AppiumServer,
169:     parsedArgs: ServerInitData['parsedArgs'],
170:     normalizedBasePath: string,
171:   ): void {
172:     const protocol = server.isSecure() ? 'https' : 'http';
173:     const address = net.isIPv6(parsedArgs.address) ? `[${parsedArgs.address}]` : parsedArgs.address;
174:     logServerAddress(`${protocol}://${address}:${parsedArgs.port}${normalizedBasePath}`);
175:   }
