20:   /**
21:    * This method takes a string which is executed as javascript in the context of
22:    * a new nodejs VM, and which has available a webdriverio driver object, having
23:    * already been attached to the currently running session.
24:    *
25:    * @param next - standard behaviour for executeDriverScript
26:    * @param driver - Appium driver handling this command
27:    * @param script - the string representing the driver script to run
28:    * @param scriptType - the name of the driver script library (currently only webdriverio is supported). Defaults to `'webdriverio'`.
29:    * @param timeoutMs - timeout for the script process. Defaults to `3600000`.
30:    * @returns a JSONifiable object representing the return value of the script
31:    * @throws {Error}
32:    */
33:   executeDriverScript: PluginCommand<
34:     ExternalDriver,
35:     [script: string, scriptType?: string, timeoutMs?: number],
36:     any
37:   > = async (
38:     next: NextPluginCallback,
39:     driver: ExternalDriver,
40:     script: string,
41:     scriptType: string = 'webdriverio',
42:     timeoutMs: number = DEFAULT_SCRIPT_TIMEOUT_MS,
43:   ) => {
44:     if (!driver.isFeatureEnabled(FEAT_FLAG)) {
45:       throw new Error(
46:         `Execute driver script functionality is not available ` +
47:           `unless server is started with --allow-insecure including ` +
48:           `the '${FEAT_FLAG}' flag, e.g., ` +
49:           `--allow-insecure=${driver.opts.automationName ?? '*'}:${FEAT_FLAG}`,
50:       );
51:     }
52: 
53:     if (scriptType !== SCRIPT_TYPE_WDIO) {
54:       throw new TypeError(`Only the '${SCRIPT_TYPE_WDIO}' script type is currently supported`);
55:     }
56: 
57:     if (!driver.serverHost || !driver.serverPort) {
58:       throw new Error(
59:         'Address or port of running server were not defined; this ' +
60:           'is required. This is probably a programming error in the driver',
61:       );
62:     }
63: 
64:     if (typeof timeoutMs !== 'number' || Number.isNaN(timeoutMs)) {
65:       throw new TypeError('Timeout parameter must be a number');
66:     }
67: 
68:     const driverOpts = {
69:       sessionId: driver.sessionId,
70:       options: {
71:         // Appium probably won't be behind ssl locally; if it ever is, might need to update this to
72:         // provide a user configurable parameter
73:         protocol: 'http',
74:         hostname: driver.serverHost,
75:         port: driver.serverPort,
76:         path: driver.serverPath,
77:       },
78:       isW3C: true,
79:       isMobile: true,
80:       capabilities: driver.caps,
81:     };
82:     this.log.info(
83:       `Constructed webdriverio driver options; W3C mode is ${driverOpts.isW3C ? 'on' : 'off'}`,
84:     );
85: 
86:     // fork the execution script as a child process
87:     const childScript = require.resolve('./execute-child.js');
88:     this.log.info(`Forking process to run webdriver script as child using ${childScript}`);
89:     const scriptProc = cp.fork(childScript);
90: 
91:     // keep track of whether we have canceled the script timeout, so we can stop
92:     // waiting for it and allow this process to finish gracefully
93:     let timeoutCanceled = false;
94: 
95:     try {
96:       const timer = new timing.Timer();
97:       timer.start();
98: 
99:       // promise that deals with the result from the child process
100:       const waitForResult = async () => {
101:         const res = await new Promise<{error?: {message: string}; success?: any}>((resolve) => {
102:           scriptProc.once('message', resolve); // this is node IPC
103:         });
104: 
105:         this.log.info('Received execute driver script result from child process, shutting it down');
106: 
107:         if (res.error) {
108:           throw new Error(res.error.message);
109:         }
110: 
111:         return res.success;
112:       };
113: 
114:       // promise that waits up to the timeout and throws an error if so, or does
115:       // nothing if the timeout is canceled because we got a result from the
116:       // child script
117:       const waitForTimeout = async () => {
118:         while (!timeoutCanceled && timer.getDuration().asMilliSeconds < timeoutMs) {
119:           await new Promise((resolve) => setTimeout(resolve, 500));
120:         }
121: 
122:         if (timeoutCanceled) {
123:           return;
124:         }
125: 
126:         throw new Error(
127:           `Execute driver script timed out after ${timeoutMs}ms. ` +
128:             `You can adjust this with the 'timeout' parameter.`,
129:         );
130:       };
131: 
132:       // now that the child script is alive, send it the data it needs to start
133:       // running the driver script
134:       this.log.info('Sending driver and script data to child');
135:       scriptProc.send({driverOpts, script, timeoutMs});
136: 
137:       // and set up a race between the response from the child and the timeout
138:       return await Promise.race([waitForResult(), waitForTimeout()]);
139:     } catch (err: any) {
140:       throw new Error(`Could not execute driver script. Original error was: ${err}`, {cause: err});
141:     } finally {
142:       // ensure we always cancel the timeout so that the timeout promise stops
143:       // spinning and allows this process to die gracefully
144:       timeoutCanceled = true;
145: 
146:       if (scriptProc.connected) {
147:         this.log.info('Disconnecting from child proc');
148:         scriptProc.disconnect();
149:       }
150: 
151:       if (scriptProc.exitCode === null) {
152:         this.log.info('Disconnecting from and killing driver script child proc');
153:         scriptProc.kill();
154:       } else {
155:         this.log.info('Script already ended on its own, no need to kill it');
156:       }
157:     }
158:   };
