13: export const MJSONWP_ELEMENT_KEY = 'ELEMENT';
14: 
15: /**
16:  * Run the script in a VM.
17:  * @param eventParams - The driver script message event parameters
18:  * @returns Promise resolving to the run script result
19:  * @throws {TypeError}
20:  */
21: async function runScript(eventParams: DriverScriptMessageEvent): Promise<RunScriptResult> {
22:   const {driverOpts, script, timeoutMs} = eventParams;
23:   if (typeof timeoutMs !== 'number' || Number.isNaN(timeoutMs)) {
24:     throw new TypeError('Timeout parameter must be a number');
25:   }
26: 
27:   /**
28:    * set up fake logger
29:    */
30:   const logs: {error: any[]; warn: any[]; log: any[]} = {
31:     error: [],
32:     warn: [],
33:     log: [],
34:   };
35:   const consoleFns: {
36:     error: (...args: any[]) => void;
37:     warn: (...args: any[]) => void;
38:     log: (...args: any[]) => void;
39:   } = {
40:     error: wrapHostBindingForVmContext((...logMsgs) => logs.error.push(...logMsgs)),
41:     warn: wrapHostBindingForVmContext((...logMsgs) => logs.warn.push(...logMsgs)),
42:     log: wrapHostBindingForVmContext((...logMsgs) => logs.log.push(...logMsgs)),
43:   };
44: 
45:   const {attach} = await import('webdriverio');
46: 
47:   const driver = await attach(driverOpts);
48:   const sandboxDriver = wrapHostBindingForVmContext(driver);
49:   const sandboxConsole = wrapHostBindingForVmContext(consoleFns);
50:   const sandboxSetTimeout = wrapHostBindingForVmContext(setTimeout);
51:   const sandboxClearTimeout = wrapHostBindingForVmContext(clearTimeout);
52: 
53:   const fullScript = `(async () => {${script}})();`;
54: 
55:   log.info('Running driver script in Node vm');
56: 
57:   // run the driver script, giving user access to the driver object, a fake console logger,
58:   // and standard setTimeout/clearTimeout functions. Each host value is proxied so
59:   // main-realm prototype metadata cannot be used to obtain the host `Function` (VM escape).
60:   let result = await vm.runInNewContext(
61:     fullScript,
62:     {
63:       driver: sandboxDriver,
64:       console: sandboxConsole,
65:       setTimeout: sandboxSetTimeout,
66:       clearTimeout: sandboxClearTimeout,
67:     },
68:     {timeout: timeoutMs, breakOnSigint: true},
69:   );
70: 
71:   result = coerceScriptResult(result);
72:   log.info('Successfully ensured driver script result is appropriate type for return');
73:   return {result, logs};
74: }
75: 
76: /**
77:  * We can get any manner of crazy thing back from a vm executing untrusted
78:  * code. We might also get WebdriverIO objects that aren't suitable for JSON
79:  * response. So make sure we convert the things we know about to their
80:  * appropriate response format, and squash other weird things.
81:  *
82:  * @param obj - object to convert and sanitize
83:  * @return safely converted object
84:  */
85: function coerceScriptResult(obj: any): any {
86:   // first ensure obj is of a type that can be JSON encoded safely. This will
87:   // get rid of custom objects, functions, etc... and turn them into POJOs
88:   try {
89:     obj = JSON.parse(JSON.stringify(obj));
90:   } catch {
91:     log.warn(
92:       'Could not convert executeDriverScript to safe response!' +
93:         `Result was: ${JSON.stringify(obj)}. Will make it null`,
94:     );
95:     return null;
96:   }
97: 
98:   let res: any;
99: 
100:   // now we begin our recursive case options
101:   if (util.isPlainObject(obj)) {
102:     // if we have an object, it's either an element object or something else
103:     // webdriverio has no monadic object types other than element and driver,
104:     // and we don't want to allow special casing return of driver
105:     res = {};
106: 
107:     if (obj[MJSONWP_ELEMENT_KEY] || obj[W3C_ELEMENT_KEY]) {
108:       // if it's an element object, clear out anything that's not the key, and then return the
109:       // object. Note that if the element object contains only one element key type (MJSONWP or
110:       // W3C), keep it that way in our response. But if the element contains both key types
111:       // (because the client is being backwards compatible) then keep both keys in our response as
112:       // well.
113:       if (obj[MJSONWP_ELEMENT_KEY]) {
114:         res[MJSONWP_ELEMENT_KEY] = obj[MJSONWP_ELEMENT_KEY];
115:       }
116: 
117:       if (obj[W3C_ELEMENT_KEY]) {
118:         res[W3C_ELEMENT_KEY] = obj[W3C_ELEMENT_KEY];
119:       }
120:       return res;
121:     }
122: 
123:     // otherwise, recurse into the object
124:     for (const key of Object.keys(obj)) {
125:       res[key] = coerceScriptResult(obj[key]);
126:     }
127:     return res;
128:   }
129: 
130:   // also handle arrays
131:   if (Array.isArray(obj)) {
132:     return obj.map(coerceScriptResult);
133:   }
134: 
135:   // base case, if it's not an object or array, return straightaway
136:   return obj;
137: }
138: 
139: /**
140:  * Entry point to runScript
141:  * @param eventParams - The driver script message event parameters
142:  */
143: async function main(eventParams: DriverScriptMessageEvent): Promise<void> {
144:   /**
145:    * keep the response of runScript
146:    */
147:   let res: ScriptResult;
148:   log.info('Parameters received from parent process');
149:   try {
150:     res = {success: await runScript(eventParams)};
151:     log.info('runScript success');
152:   } catch (error: any) {
153:     log.info('runScript error');
154:     res = {error: {message: error.message, stack: error.stack}};
155:   }
156:   await send(res);
157: }
158: 
159: // ensure we're running this script in IPC mode
160: if (require.main === module && typeof process.send === 'function') {
161:   send = promisify(process.send).bind(process) as (res: ScriptResult) => Promise<void>;
162:   log.info('Running driver execution in child process');
163:   process.on('message', main);
164: }

